(()=>{'use strict';const EN=document.documentElement.lang==='en',T=(v,e)=>EN?e:v,txt=x=>x[EN?'en':'vi'],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const host=document.getElementById('roadmap-root');
fetch('roadmap-data.json').then(r=>{if(!r.ok)throw Error('roadmap');return r.json()}).then(d=>{
host.innerHTML=`<section id="roadmap"><div class="eyebrow">${T('Roadmap v1.1 · Grand Park là case nghiên cứu','Roadmap v1.1 · Grand Park case study')}</div><h2>${T('Bắt đầu từ căn chưa bán. Xây một nền tảng có thể nhân rộng.','Start with unsold units. Build a repeatable platform.')}</h2><p class="rm-lead">${T('Ưu tiên căn hộ và shophouse hiện hữu thuộc chủ đầu tư, đang chào bán và được đồng ý đưa vào cấu trúc token hóa. Kênh retail phát triển song song để kiểm chứng nhu cầu trước khi mở giao dịch thật.','Prioritize existing developer-owned apartments and shophouses offered for sale with consent to tokenization. Build retail channels in parallel to validate demand before actual transactions.')}</p><div class="rm-status"><b>${T('Đã có','Available')}</b><span>${T('Site Việt–Anh · dữ liệu phân khu có nguồn · mô phỏng quy trình','VI/EN site · sourced subdivision references · workflow simulations')}</span><b>${T('Chưa có','Not available')}</b><span>${T('Quỹ căn thực được xác nhận · đối tác cam kết · hợp đồng onchain · huy động tiền thật','Verified actual inventory · committed partners · deployed contracts · actual fundraising')}</span></div><p class="muted">${T('Các mốc, số căn và chỉ tiêu dưới đây là mục tiêu đề xuất, không phải kết quả đã đạt. Chuyển giai đoạn theo điều kiện nghiệm thu, không cam kết ngày mở bán.','Milestones, unit counts and metrics below are proposed targets, not achievements. Progress depends on exit gates, not a promised sale date.')}</p><div class="rm-phase-grid" role="group" aria-label="${T('Chọn chặng roadmap','Select a roadmap phase')}">${d.phases.map((p,i)=>`<button data-phase="${i}" aria-pressed="${i===0}"><small>${p.id} · ${esc(txt(p.status))}</small><b>${esc(txt(p.title))}</b></button>`).join('')}</div><article id="rm-phase" aria-live="polite"></article><p class="rm-dependencies">${T('R1 · Quỹ căn, R2 · testnet và R3 · retail có thể chạy song song sau R0. R4 chỉ mở khi đủ các điều kiện; R4 lặp test → sửa lỗi → cải tiến → test lại; nghiệm thu rồi mới R5 nhân rộng nội bộ tập đoàn, sau đó R6 bán giải pháp ra ngoài.','R1 inventory, R2 testnet and R3 retail may run in parallel after R0. R4 requires all launch gates; R4 repeats test → fix → improve → retest; acceptance precedes R5 internal group rollout, then R6 external solution sales.')}</p><details class="rm-brain"><summary>${T('Bộ não vận hành: AI đề xuất, bằng chứng quyết định','Operating brain: AI suggests, evidence gates decide')}</summary><p>${T('Nhận dữ liệu → chuẩn hóa theo mã căn → kiểm tra nguồn và quyền ký → áp quy tắc → chờ / từ chối / đủ điều kiện / tạm dừng → thực thi phần được phép → đối soát. Không để AI tự tạo xác nhận ngân hàng hoặc vượt điều kiện phát hành.','Input → normalize by property → validate source and signing authority → apply rules → hold / reject / ready / pause → permitted execution → reconciliation. AI cannot fabricate bank attestations or bypass issuance gates.')}</p><ol>${d.rules.map((r,i)=>'<li><b>G'+(i+1)+'</b> '+esc(txt(r))+'</li>').join('')}</ol></details><div class="rm-decision"><div><div class="eyebrow">${T('Thử bộ não bằng tình huống','Try the rules with a scenario')}</div><label for="rm-case">${T('Chọn dữ liệu đầu vào giả lập','Choose simulated inputs')}</label><select id="rm-case"><option value="candidate">${T('Căn chủ đầu tư chưa bán, hồ sơ còn thiếu','Unsold developer unit; evidence incomplete')}</option><option value="ready">${T('Đủ xác nhận và quyền phát hành trong demo','All demo attestations and issuance rights satisfied')}</option><option value="forged">${T('Xác nhận sai người ký hoặc đã hết hạn','Wrong signer or expired attestation')}</option><option value="unfunded">${T('Có hợp đồng thuê, quỹ chưa nhận được tiền','Active lease; rental vault not funded')}</option><option value="stale">${T('Định giá hết hạn, tiền thuê đã đủ quỹ','Expired valuation; rental vault funded')}</option><option value="incident">${T('Ví nghi bị hack, cần khóa chuyển nhượng','Suspected wallet compromise; freeze transfers')}</option></select></div><div class="result"><small>${T('QUYẾT ĐỊNH MÔ PHỎNG','SIMULATED DECISION')}</small><h3 id="rm-decision-title" aria-live="polite"></h3><p id="rm-decision-reason"></p><small>${T('Không có giao dịch, xác nhận thật hoặc thay đổi quyền sở hữu.','No transaction, actual attestation or ownership change.')}</small></div></div><h3>${T('Kênh tiếp cận nhà đầu tư nhỏ lẻ','Retail audience channels')}</h3><div class="rm-channel-grid">${d.channels.map(c=>'<article><h4>'+esc(typeof c.channel==='string'?c.channel:txt(c.channel))+'</h4><p>'+esc(txt(c.purpose))+'</p><p class="muted">'+esc(txt(c.content))+'</p><small>'+T('Đo: ','Measure: ')+esc(txt(c.metric))+'</small></article>').join('')}</div><div class="rm-funnel"><h3>${T('Phễu đề xuất','Proposed audience journey')}</h3><ol>${[T('Hiểu sản phẩm qua nội dung','Learn through educational content'),T('Vào site và hoàn tất demo','Visit the site and complete the demo'),T('Bày tỏ quan tâm có đồng ý','Express interest with consent'),T('Kiểm tra điều kiện tham gia','Check participation eligibility'),T('Giao dịch chỉ sau khi mở hợp lệ','Transact only after valid launch'),T('Nhận báo cáo và được hỗ trợ','Receive reporting and support')].map(x=>'<li>'+x+'</li>').join('')}</ol><p class="muted">${T('Hiện mới có site và demo. Form quan tâm, CRM, tracking và kênh phân phối đối tác chưa được triển khai; chưa thu tiền đăng ký. Mục tiêu tiếp cận từ 1–2 USD còn cần kiểm chứng chi phí phục vụ.','Only the site and demo exist today. Interest forms, CRM, tracking and partner distribution are not implemented; no registration funds are collected. The USD 1–2 access ambition still needs servicing-cost validation.')}</p></div><div class="rm-business"><h3>${T("Mua token từng căn ngay trên site — thiết kế mục tiêu","Buy property-specific tokens on this site — planned flow")}</h3><p>${T("Chọn căn → xem hồ sơ, quyền, giá, phí và tiền thuê → kiểm tra điều kiện tham gia → kết nối ví hoặc kênh thanh toán được hỗ trợ → xác nhận giao dịch → thanh toán và nhận token đúng căn → theo dõi quyền sở hữu và tiền thuê. Hợp đồng kiểm tra nguồn cung, quyền, xác nhận và trạng thái tài sản; thanh toán lỗi không được ghi nhận là mua thành công. Site hiện chưa có checkout thật, kết nối ví hay nhận tiền mua token.","Choose a property → review evidence, rights, price, fees and rent → eligibility checks → supported wallet/payment connection → confirm → settle and receive that property’s token → track holdings and rent. Contracts check supply, permissions, attestations and asset status; failed settlement must not be recorded as a successful purchase. Actual checkout, wallet connection and token payments are not live.")}</p></div><div class="rm-business"><h3>${T('Doanh thu từ dịch vụ, không từ bán altcoin','Revenue from services, not altcoin sales')}</h3><p>${T('Ưu tiên phí triển khai doanh nghiệp + thuê nền tảng hằng năm. Phí giao dịch thành công hoặc dịch vụ vận hành bổ sung theo hợp đồng; không tính hai lần cùng một công việc. Tiền mua bất động sản, tiền thuê và doanh thu phí phải tách riêng.','Prioritize enterprise implementation + annual subscriptions. Add transaction-success or servicing fees only under agreement, without duplicate charges. Separate property proceeds, rental funds and platform fee revenue.')}</p></div><p class="rm-downloads"><a href="Fual_Property_Roadmap_GrandPark_20261108_${EN?'en':'vi'}.md" download>${T('Tải roadmap chi tiết tiếng Việt','Download the detailed English roadmap')} ↗</a> · <a href="#workflows">${T('Bấm thử workflow ba lớp','Explore the three-layer walkthroughs')} ↗</a></p></section>`;
function phase(i){const p=d.phases[i];document.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.phase)===i)));document.getElementById('rm-phase').innerHTML=`<div class="rm-phase-heading"><span>${p.id}</span><div><small>${esc(txt(p.status))}</small><h3>${esc(txt(p.title))}</h3></div></div><p>${esc(txt(p.goal))}</p><div class="rm-three">${[['real',T('Lớp thực tế','Real-world layer')],['verify',T('Lớp xác nhận','Attestation layer')],['chain',T('Lớp hợp đồng','Contract layer')]].map(([k,l])=>'<div><b>'+l+'</b><p>'+esc(txt(p[k]))+'</p></div>').join('')}</div><dl><dt>${T('Đầu ra','Deliverables')}</dt><dd>${esc(txt(p.output))}</dd><dt>${T('Điều kiện chuyển bước','Exit gate')}</dt><dd>${esc(txt(p.gate))}</dd><dt>${T('Thước đo đề xuất','Proposed measures')}</dt><dd>${esc(txt(p.metric))}</dd></dl>`;}
document.querySelectorAll('[data-phase]').forEach(b=>b.addEventListener('click',()=>phase(Number(b.dataset.phase))));phase(0);
const decisions={candidate:[T('CHỜ BỔ SUNG · G1','HOLD · G1'),T('Đây là ứng viên ưu tiên R1. Chưa đủ hồ sơ và sự đồng ý thì chưa mở phát hành. Không lấy Available thay bằng chứng quyền sở hữu.','This is a priority R1 candidate. Missing evidence or consent blocks issuance. Available is not proof of title.')],ready:[T('ĐỦ ĐIỀU KIỆN GIẢ LẬP · G1–G3','DEMO READY · G1–G3'),T('Bộ điều kiện giả lập đạt. Trong sản phẩm thật, hợp đồng còn phải kiểm tra xác nhận, tổng cung, thanh toán và quyền hợp lệ trước hành động.','Simulated prerequisites pass. In production the contract must still verify attestations, supply, settlement and valid rights before acting.')],forged:[T('TỪ CHỐI · G2','REJECT · G2'),T('Không chấp nhận xác nhận sai thẩm quyền, hết hạn hoặc sai phiên bản. Yêu cầu xác nhận mới từ đúng bên; AI không tự bổ sung chữ ký.','Reject unauthorized, expired or wrong-version attestations. Obtain a new attestation from the correct party; AI cannot supply a signature.')],unfunded:[T('CHỜ CẤP QUỸ · G4','AWAIT FUNDING · G4'),T('Chưa phân phối tiền chưa có trong quỹ. Ghi đúng khoản phải thu và đối soát; không lấy tiền căn khác để bù.','Do not distribute money absent from the vault. Record receivables and reconcile; do not use another property’s funds.')],stale:[T('CHỜ GIÁ MỚI · G5','AWAIT VALUATION · G5'),T('Chặn giao dịch mới cần định giá còn hạn. Tiền thuê đã đủ quỹ có thể tiếp tục theo điều kiện riêng, không tự bị khóa bởi sự cố giá.','Block new trades requiring a valid valuation. Funded rent may proceed under its separate rules; a valuation issue does not automatically freeze it.')],incident:[T('TẠM DỪNG ĐÚNG PHẠM VI · G6','SCOPED PAUSE · G6'),T('Chuyển sang quy trình ứng cứu: người có quyền xác nhận lệnh khóa. Giữ quyền thuê đã tích lũy; mở khóa cần phê duyệt.','Enter incident response: an authorized actor confirms the freeze. Preserve accrued rental rights; unfreezing requires approval.')]};function decision(){const x=decisions[document.getElementById('rm-case').value];document.getElementById('rm-decision-title').textContent=x[0];document.getElementById('rm-decision-reason').textContent=x[1]}document.getElementById('rm-case').addEventListener('change',decision);decision();
}).catch(()=>host.innerHTML='<section id="roadmap"><h2>'+T('Chưa tải được roadmap','Roadmap could not be loaded')+'</h2><p>'+T('Vui lòng tải lại trang.','Please reload the page.')+'</p></section>');
})();
